-- NIS Skill Tree: split "Rapid Prototyping" into three areas (run ONCE in Supabase > SQL Editor)
-- 3D Printing & Scanning (keeps the old area id 'rp'), Laser Engraving ('laser'), Electronics & Robotics ('elec').
-- Every existing sign-off, request and history entry is kept: skills move with their ids.
-- The vinyl cutter skill moves to Design. Nothing in any other area is touched (your Woodshop edits are safe).
-- New areas start with no lead; set one in the site under Skills > Edit tree.
-- Run 5_area_colors.sql first if you have not already.
begin;

alter table public.areas add column if not exists color text;

update public.areas set name = '3D Printing & Scanning', color = coalesce(color, '#ffd74e') where id = 'rp';
on conflict (id) do nothing;
update public.areas set sort = case id when 'wood' then 1 when 'metal' then 2 when 'rp' then 3 when 'laser' then 4 when 'elec' then 5 when 'cer' then 6 when 'des' then 7 when 'tex' then 8 else sort + 8 end;

on conflict do nothing;

-- vinyl cutter -> Design (Bronze elective, listed last)
update public.skills set area = 'des', sort = 9001,
  description = replace(description, 'Rapid Prototyping', 'Design')
 where id = 'rp-bronze-e3' and area = 'rp';

-- moved skills (sign-offs come with them)
update public.skills set area = 'rp', kind = 'req', sort = 5001, description = replace(description, 'Rapid Prototyping', '3D Printing & Scanning') where id = 'rp-bronze-r1';
update public.skills set area = 'rp', kind = 'el', sort = 5003, description = replace(description, 'Rapid Prototyping', '3D Printing & Scanning') where id = 'rp-bronze-e1';
update public.skills set area = 'rp', kind = 'el', sort = 5004, description = replace(description, 'Rapid Prototyping', '3D Printing & Scanning') where id = 'rp-bronze-e4';
update public.skills set area = 'rp', kind = 'cap', sort = 5007, name = 'Teach the 3D Printing & Scanning SOP', description = 'Capstone for 3D Printing & Scanning Bronze. Teach the entry-level 3D Printing & Scanning SOP to members on your own, with a staff member observing.' where id = 'rp-bronze-cap';
update public.skills set area = 'rp', kind = 'req', sort = 5008, description = replace(description, 'Rapid Prototyping', '3D Printing & Scanning') where id = 'rp-silver-r2';
update public.skills set area = 'rp', kind = 'el', sort = 5010, description = replace(description, 'Rapid Prototyping', '3D Printing & Scanning') where id = 'rp-silver-e1';
update public.skills set area = 'rp', kind = 'el', sort = 5011, description = replace(description, 'Rapid Prototyping', '3D Printing & Scanning') where id = 'rp-silver-e2';
update public.skills set area = 'rp', kind = 'el', sort = 5012, description = replace(description, 'Rapid Prototyping', '3D Printing & Scanning') where id = 'rp-silver-e4';
update public.skills set area = 'rp', kind = 'cap', sort = 5014, name = 'Lead an advanced 3D printing & scanning workshop', description = 'Capstone for 3D Printing & Scanning Silver. Plan and run an advanced training or workshop in 3D Printing & Scanning.' where id = 'rp-silver-cap';
update public.skills set area = 'rp', kind = 'req', sort = 5015, description = replace(description, 'Rapid Prototyping', '3D Printing & Scanning') where id = 'rp-gold-r2';
update public.skills set area = 'rp', kind = 'el', sort = 5017, description = replace(description, 'Rapid Prototyping', '3D Printing & Scanning') where id = 'rp-gold-e1';
update public.skills set area = 'rp', kind = 'el', sort = 5018, description = replace(description, 'Rapid Prototyping', '3D Printing & Scanning') where id = 'rp-gold-e3';
update public.skills set area = 'rp', kind = 'el', sort = 5019, description = replace(description, 'Rapid Prototyping', '3D Printing & Scanning') where id = 'rp-gold-e4';
update public.skills set area = 'rp', kind = 'cap', sort = 5021, name = 'Develop a new 3D printing & scanning workshop', description = 'Capstone for 3D Printing & Scanning Gold. Design a new workshop, training or curriculum for 3D Printing & Scanning that NIS can keep offering.' where id = 'rp-gold-cap';
update public.skills set area = 'laser', kind = 'req', sort = 5022, description = replace(description, 'Rapid Prototyping', 'Laser Engraving') where id = 'rp-bronze-r2';
update public.skills set area = 'laser', kind = 'el', sort = 5024, description = replace(description, 'Rapid Prototyping', 'Laser Engraving') where id = 'rp-bronze-e2';
update public.skills set area = 'laser', kind = 'req', sort = 5029, description = replace(description, 'Rapid Prototyping', 'Laser Engraving') where id = 'rp-silver-r1';
update public.skills set area = 'laser', kind = 'el', sort = 5031, description = replace(description, 'Rapid Prototyping', 'Laser Engraving') where id = 'rp-silver-e3';
update public.skills set area = 'laser', kind = 'req', sort = 5036, description = replace(description, 'Rapid Prototyping', 'Laser Engraving') where id = 'rp-gold-r1';
update public.skills set area = 'laser', kind = 'el', sort = 5038, description = replace(description, 'Rapid Prototyping', 'Laser Engraving') where id = 'rp-gold-e2';

-- new skills
on conflict (id) do nothing;

 where exists (select 1 from information_schema.columns where table_schema='public' and table_name='activity_log' and column_name='text');

commit;

-- check: should list 3D Printing & Scanning, Laser Engraving, Electronics & Robotics with 21 skills each
select a.name, count(s.id) as skills from public.areas a left join public.skills s on s.area = a.id and not s.retired group by a.name, a.sort order by a.sort;
